/* This will inject the Protogen globally */
html::after {
    content: "";
    position: fixed;
    
    /* Position him in the corner */
    bottom: 15px;
    right: 15px;
    
    /* Size - adjust as you like */
    width: 125px;
    height: 125px;
    
    /* INSERT YOUR IMAGE LINK BELOW */
    background-image: url(https://tenor.com/view/protogen-spin-cute-you-spin-me-furry-gif-23040103);
    
    background-size: contain;
    background-repeat: no-repeat;
    
    /* The "Stay on top" layer */
    z-index: 2147483647; 
    
    /* Click-through so he doesn't block buttons */
    pointer-events: none; 
    
    /* Optional: slightly see-through so he's not too distracting */
    opacity: 0.85; 
}
